INSERT INTO "emission_factors" (
  "id", "factor_library_id", "external_id", "scope", "emission_category_id", "activity_type",
  "geography_country", "input_unit", "co2e", "usage_notes"
)
SELECT gen_random_uuid()::text, lib."id", src."external_id", c."scope", c."id", src."activity_type",
       src."geography_country", src."input_unit", src."co2e", src."usage_notes"
FROM src
JOIN "emission_categories" c ON c."code" = src."category_code"
CROSS JOIN lib
WHERE NOT EXISTS (
  SELECT 1 FROM "emission_factors" e WHERE e."factor_library_id" = lib."id" AND e."external_id" = src."external_id"
);

WITH lib26 AS (
  SELECT "id" FROM "factor_libraries" WHERE "name" = 'DEFRA' AND "version" = '2026.1'
), carried AS (
  SELECT DISTINCT ON (f."external_id") f.*
  FROM "emission_factors" f
  JOIN "factor_libraries" l ON l."id" = f."factor_library_id"
  WHERE l."name" = 'DEFRA' AND l."version" = '2025.1'
    AND f."external_id" NOT IN ('defra-2025-car-avg-km', 'defra-2025-car-bev-medium-km', 'defra-2025-car-diesel-large-km', 'defra-2025-car-diesel-medium-km', 'defra-2025-car-diesel-small-km', 'defra-2025-car-petrol-large-km', 'defra-2025-car-petrol-medium-km', 'defra-2025-car-petrol-small-km', 'defra-2025-car-phev-avg-km', 'defra-2025-cng-kg', 'defra-2025-diesel-litre', 'defra-2025-hvo-litre', 'defra-2025-lng-kg', 'defra-2025-motorbike-avg-km', 'defra-2025-petrol-litre', 'defra-2025-van-diesel-km', 'defra-2025-van-electric-km', 'defra-2025-burning-oil-litre', 'defra-2025-coal-industrial-kg', 'defra-2025-diesel-stationary-litre', 'defra-2025-gasoil-litre', 'defra-2025-heavyfueloil-litre', 'defra-2025-lpg-litre', 'defra-2025-natgas-kwh', 'defra-2025-wood-chips-kg', 'defra-2025-wood-pellets-kg', 'defra-2025-elec-uk-lb-kwh', 'defra-2025-electricity-lb-kwh', 'defra-2025-elec-uk-td-kwh', 'defra-2025-electricity-mb-kwh', 'defra-2025-air-long-haul-km', 'defra-2025-air-short-haul-km', 'defra-2025-biz-bus-local-pkm', 'defra-2025-biz-car-avg-km', 'defra-2025-biz-car-bev-km', 'defra-2025-biz-coach-pkm', 'defra-2025-biz-eurostar-pkm', 'defra-2025-biz-flight-domestic-econ-pkm', 'defra-2025-biz-flight-longhaul-biz-pkm', 'defra-2025-biz-flight-longhaul-econ-pkm', 'defra-2025-biz-flight-longhaul-first-pkm', 'defra-2025-biz-flight-shorthaul-biz-pkm', 'defra-2025-biz-flight-shorthaul-econ-pkm', 'defra-2025-biz-motorbike-km', 'defra-2025-biz-rail-national-pkm', 'defra-2025-biz-rail-tube-pkm', 'defra-2025-biz-taxi-avg-km', 'defra-2025-car-average-km', 'defra-2025-rail-uk-km', 'defra-2025-commute-bus-pkm', 'defra-2025-commute-car-avg-km', 'defra-2025-commute-car-bev-km', 'defra-2025-commute-motorbike-km', 'defra-2025-commute-rail-pkm', 'defra-2025-freight-air-tkm', 'defra-2025-freight-rail-tkm', 'defra-2025-freight-sea-container-tkm', 'defra-2025-hgv-40t-tkm', 'defra-2025-hgv-7.5t-tkm', 'defra-2025-hgv-artic-avg-tkm', 'defra-2025-hgv-avg-tkm', 'defra-2025-hgv-rigid-avg-tkm', 'defra-2025-van-avg-km', 'defra-2025-van-diesel-tkm', 'defra-2025-waste-efw-incineration', 'defra-2025-waste-incineration-kg', 'defra-2025-waste-inert-landfill', 'defra-2025-waste-landfill-mixed-kg', 'defra-2025-waste-mixed-landfill', 'defra-2025-waste-mixed-recycling', 'defra-2025-waste-recycled-mixed-kg', 'defra-2025-waste-wood-landfill')
